import {ProgramBuilder,instruction,variable,showUI,hideUI,waitUI,setUIInput,uiCatalog,uiScreen,uiButton,uiInput,uiToggle,uiRange,uiLabel,uiImage,uiField,flowchart,flowChapter,flowNode,visitNode,expr,randomI32,videoPlay,interactionPrompt,codec,defineOperation,createOperationRegistry,waitFor,sceneExtra,sceneMarker,extrasCatalog} from 'galbox-sdk/port-kit';
import type {Asset} from 'galbox-sdk/protocol';
import {string,bool,i32} from 'galbox-sdk/protocol';

export function interactiveRegistry(initialized:()=>void=()=>{},implementation='mod.counter@1'){
 const integer=codec.integer('mod.integer'),args=codec.object('mod.args',{step:integer}),state=codec.object('mod.state',{total:integer}),resume=codec.object('mod.resume',{kind:codec.literal('mod.finish','finish'),amount:integer});
 const operation=defineOperation({id:'mod.counter',version:1,args,state,resume,manifest:{implementation,save:'safe',restore:'continue',resumeKinds:['finish'],jumpTargets:[],recipe:false},initialize(){initialized();return {total:0};},reduce(input,s){const total=s.total+(input.kind==='start'?input.args.step:input.event.amount);return {state:{total},actions:[{type:'set',dest:'count',value:i32(total)}],effects:input.kind==='start'?[{type:'audio',task:'operation-tone',asset:'tone',channel:'sfx',gain:0,loop:true,restore:'replay'}]:[],flow:input.kind==='start'?{kind:'wait',wait:waitFor(resume,'finish','receipt')}:{kind:'continue'}};}});
 return {operation,operations:createOperationRegistry([operation])};
}
export function interactiveParts(image:Asset,video:Asset,tone:Asset,restore:'replay'|'forbid'='replay'){
 const b=new ProgramBuilder({gameId:'interactive-modules',title:'Original modular keeper console',release:'interactive-v2',entry:'main'}),art=b.asset('image',image),clip=b.asset('video',video),button=variable('button','string'),name=variable('name','string'),power=variable('power','i32'),lit=variable('lit','bool'),draw=variable('draw','i32'),route=variable('route','string');
 b.global({...button,initial:string('')}).global({...name,initial:string('unset')}).global({...power,initial:i32(0)}).global({...lit,initial:bool(false)}).global({...draw,initial:i32(0)}).global({...route,initial:string('')}).global({id:'count',kind:'i32',initial:i32(0)}).rng(41).capability('operations');
  b.asset('audio',tone);
 const pos=(x:number,y:number,width=240,height=50)=>({x,y,width,height}),submit=uiButton('submit',{rect:pos(50,450),text:'Submit shift'}),field=uiInput('name','Default keeper',{rect:pos(50,100,400),text:'Keeper',maxLength:32}),toggle=uiToggle('lit',true,{rect:pos(50,200),text:'Light enabled'}),range=uiRange('power',40,{rect:pos(50,300,400),text:'Power',min:0,max:100,step:5}),label=uiLabel('label',{rect:pos(50,30,600),text:'Original keeper console'}),picture=uiImage('art',art,{rect:pos(600,50,200,200),text:'Beacon'}),screen=uiScreen('console','Keeper console',[label,field,toggle,range,picture,submit]),node=flowNode('shift',{chapter:'shifts',title:'Next shift',entry:'chapter',unlock:expr.flag(true)});
 const scene=sceneExtra('console-replay','scene',{title:'Console replay',unlock:expr.flag(true)});b.extras(extrasCatalog('replays','v1',[scene]));
 b.ui(uiCatalog('console','v1',[screen])).flowchart(flowchart('shifts','v1',[flowChapter('shifts','Shifts')],[node]));
 const page=(at:string,content:string)=>instruction('text.page',{at,textId:at,revision:'v1',speaker:'Keeper',content}),ret=(at:string)=>instruction('control.return',{at}),call=(at:string,fn:string)=>instruction('control.call',{at,function:fn,args:[]});
 const {operation}=interactiveRegistry();
 b.function({id:'main',entry:'intro',layout:1,params:[],locals:[],returns:'void',code:[page('intro','Begin the next keeper shift.'),call('show-call','show'),call('form-call','form'),call('operation-call','counter'),call('video-call','video'),randomI32('draw',draw,expr.integer(0),expr.integer(999)),call('timed-call','timed'),instruction('control.end',{at:'end'})]});
 b.function({id:'show',entry:'show',layout:1,params:[],locals:[],returns:'void',code:[showUI('show',screen),setUIInput('preset',screen,field,expr.text('Script keeper')),ret('show-return')]});
 b.function({id:'form',entry:'form-wait',layout:1,params:[],locals:[],returns:'void',code:[waitUI('form-wait',screen,button,[{control:submit,target:'form-hide'}],[uiField(field,name),uiField(toggle,lit),uiField(range,power)]),hideUI('form-hide'),ret('form-return')]});
 b.function({id:'counter',entry:'counter',layout:1,params:[],locals:[],returns:'void',code:[operation.invocation('counter',{step:3}),ret('counter-return')]});
 b.function({id:'video',entry:'video',layout:1,params:[],locals:[],returns:'void',code:[videoPlay('video','clip',clip,{restore,gain:0,skippable:true}),ret('video-return')]});
 b.function({id:'timed',entry:'timed',layout:1,params:[],locals:[],returns:'void',code:[interactionPrompt('timed',route,'Reply before the tide',[{id:'reply',label:'Reply',target:'chosen'}],{deadlineMs:1500,timeout:{id:'tide',target:'timeout'}}),page('chosen','A reply was sent.'),ret('chosen-return'),page('timeout','The tide arrived first.'),ret('timed-return')]});
 b.function({id:'chapter',entry:'chapter-marker',layout:1,params:[],locals:[],returns:'void',code:[visitNode('chapter-marker',node),call('chapter-show','show'),call('chapter-form','form'),page('chapter-text','The next shift is ready.'),ret('chapter-return')]});
 b.function({id:'scene',entry:'scene-marker',layout:1,params:[],locals:[],returns:'void',code:[sceneMarker('scene-marker',scene),call('scene-show','show'),call('scene-form','form'),call('scene-counter','counter'),page('scene-text','A replayed shift.'),ret('scene-return')]});
 const parts=b.parts(),functions=parts.files.flatMap(f=>f.body.functions);parts.files=functions.map(f=>({uri:'code/'+f.id+'.pb',body:{format:'galbox-code',version:1,id:f.id,functions:[f]}}));return parts;
}
